CREATE TEMPORARY VIEW dim_shop_${grass_region_without_quote} AS
SELECT
    shop_id
    ,status AS shop_status
    ,user_status AS shop_seller_status
    ,is_cb_shop AS shop_is_cb_shop
    ,response_rate AS shop_response_rate
    ,seller_rating AS shop_seller_rating
    ,sold_total AS shop_sold_total
    ,rating_bad AS shop_rating_bad
    ,rating_normal AS shop_rating_normal
    ,rating_good AS shop_rating_good
    ,user_id AS shop_user_id
    ,is_b2c AS shop_is_b2c
    ,is_bi_excluded AS shop_is_bi_excluded
    ,is_ccb_shop AS shop_is_ccb_shop
    ,is_fbs AS shop_is_fbs
    ,is_fss_shop AS shop_is_fss_shop
    ,is_supermarket_shop AS shop_is_supermarket_shop
    ,CASE
        WHEN is_official_shop = 1 THEN 'official'
        WHEN is_preferred_shop = 1 THEN 'preferred'
        WHEN is_preferred_plus_shop = 1 THEN 'preferred_plus'
        ELSE 'long_tail'
    END AS shop_type
    ,shop_name
    ,is_holiday_mode AS shop_is_holiday_mode
    ,create_datetime as shop_create_datetime
    ,(
         CAST(
             get_json_object(seller_rating, '$.rating_count[0]') * 0 +
             get_json_object(seller_rating, '$.rating_count[1]') * 1 +
             get_json_object(seller_rating, '$.rating_count[2]') * 2 +
             get_json_object(seller_rating, '$.rating_count[3]') * 3 +
             get_json_object(seller_rating, '$.rating_count[4]') * 4 +
             get_json_object(seller_rating, '$.rating_count[5]') * 5
         AS DOUBLE) /
         CAST(
             get_json_object(seller_rating, '$.rating_count[0]') +
             get_json_object(seller_rating, '$.rating_count[1]') +
             get_json_object(seller_rating, '$.rating_count[2]') +
             get_json_object(seller_rating, '$.rating_count[3]') +
             get_json_object(seller_rating, '$.rating_count[4]') +
             get_json_object(seller_rating, '$.rating_count[5]')
         AS DOUBLE)
     ) AS shop_score
    ,pick_up_address.level1.value AS shop_state
    ,pick_up_address.level2.value AS shop_city
    ,pick_up_address.level3.value AS shop_district
FROM
    mp_user.dim_shop__reg_s0_live
WHERE 
    tz_type = 'local'
    AND grass_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND shop_id > 0;

--sql_divide_splitter--

