CREATE TEMPORARY VIEW shop_bd_competitor_${grass_region_without_quote} AS
SELECT
    shop_id
FROM
    mkpldp_bd_center.salesforce_metrics_reg_continuous_tab
WHERE
    (length(competitor_links) > 0
    OR length(competitor_names)>0)

UNION     -- this will calculate distinct value automatically
SELECT
    shopid as shop_id
FROM
    marketplace.shopee_pcenter_db__shop_pairs_tab__reg_daily_s0_live
WHERE
    pair_status=0
    AND shopid is not null
;
