-- Assemble small tables (shop dimensions) first
INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_shop
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    dim_shop.shop_id
    ,shop_type
    ,shop_is_cb_shop
    ,shop_response_rate
    ,shop_seller_rating
    ,shop_sold_total
    ,shop_rating_bad
    ,shop_rating_normal
    ,shop_rating_good
    ,shop_cb_shop_origin_country
    ,shop_user_id
    ,shop_is_b2c
    ,shop_is_bi_excluded
    ,shop_is_ccb_shop
    ,shop_is_fbs
    ,shop_is_fss_shop
    ,shop_is_supermarket_shop
    ,shop_name
    ,shop_follower_cnt_td
    ,shop_like_cnt_td
    ,shop_primary_managed_kpi_category
    ,shop_tier
    ,shop_status
    ,shop_seller_status
    ,shop_is_holiday_mode
    ,shop_first_listing_datetime
    ,shop_last_listing_datetime
    ,shop_active_item_with_stock_cnt
    ,shop_last_login_datetime_td
    ,CASE
        WHEN shop_bd_competitor.shop_id IS NULL THEN false
        ELSE true
    END AS shop_is_competitor
    ,shop_create_datetime
    ,shop_score
    ,shop_state
    ,shop_city
    ,shop_district

FROM
    dim_shop_${grass_region_without_quote} AS dim_shop
    LEFT JOIN dim_managed_shop_${grass_region_without_quote} AS dim_managed_shop
        ON dim_shop.shop_id = dim_managed_shop.shop_id
    LEFT JOIN dws_shop_interaction_${grass_region_without_quote} AS dws_shop_interaction
        ON dim_shop.shop_id = dws_shop_interaction.shop_id
    LEFT JOIN dws_shop_listing_${grass_region_without_quote} dws_shop_listing
        ON dim_shop.shop_id = dws_shop_listing.shop_id
    LEFT JOIN dws_shop_login_${grass_region_without_quote} dws_shop_login
        ON dim_shop.shop_id = dws_shop_login.shop_id
    LEFT JOIN shop_bd_competitor_${grass_region_without_quote} shop_bd_competitor
        ON dim_shop.shop_id = shop_bd_competitor.shop_id
    LEFT JOIN dim_shop_ext_${grass_region_without_quote} dim_shop_ext
        ON dim_shop.shop_id = dim_shop_ext.shop_id
;
